ALTER TABLE `interview_questions` ADD COLUMN `description` varchar(100) DEFAULT NULL;

UPDATE `interview_questions` SET `description` = '스스로 생각하는 장점과 아쉬운 점을 적어 보세요' WHERE `content` = '내가 생각하는 나의 장점과 단점';
UPDATE `interview_questions` SET `description` = '어떤 일을 하는지, 일하며 즐거운 순간을 적어 보세요' WHERE `content` = '현재 하고 있는 일';
UPDATE `interview_questions` SET `description` = '평일과 주말을 보통 어떻게 보내는지 적어 보세요' WHERE `content` = '나의 평일/주말 생활 패턴';
UPDATE `interview_questions` SET `description` = '요즘 나를 웃게 하는 작은 순간을 적어 보세요' WHERE `content` = '일상에서 느끼는 나의 소소한 행복';
UPDATE `interview_questions` SET `description` = '처음 봤을 때와 다른 나의 의외의 모습을 적어 보세요' WHERE `content` = '내가 생각하는 나의 반전 매력';
UPDATE `interview_questions` SET `description` = '지치거나 힘들 때 기분을 푸는 방법을 적어 보세요' WHERE `content` = '나만의 스트레스 해소 방법';
UPDATE `interview_questions` SET `description` = '즐겨 먹는 음식과 잘 안 먹는 음식을 적어 보세요' WHERE `content` = '좋아하는 음식/싫어하는 음식';
UPDATE `interview_questions` SET `description` = '요즘 배워 보고 싶은 것과 그 이유를 적어 보세요' WHERE `content` = '배우고 싶은 분야/언어';
UPDATE `interview_questions` SET `description` = '10년 뒤 어떤 모습으로 살고 싶은지 적어 보세요' WHERE `content` = '10년 후 나의 모습';
UPDATE `interview_questions` SET `description` = '나를 위해 꾸준히 하고 있는 일을 적어 보세요' WHERE `content` = '요즘 하고 있는 자기관리';
UPDATE `interview_questions` SET `description` = '지금 내 삶에서 가장 중요한 것부터 적어 보세요' WHERE `content` = '내 삶의 우선 순위(나, 가족, 연인, 친구, 커리어 등)';
UPDATE `interview_questions` SET `description` = '이성 친구 관계에 대한 생각을 솔직하게 적어 보세요' WHERE `content` = '남사친/여사친에 대한 나의 생각';
UPDATE `interview_questions` SET `description` = '친구나 동료와 어떻게 지내는 편인지 적어 보세요' WHERE `content` = '나의 인간관계 스타일';
UPDATE `interview_questions` SET `description` = '어떤 사람에게 마음이 가는지 적어 보세요' WHERE `content` = '호감을 느끼는 사람의 유형/타입';
UPDATE `interview_questions` SET `description` = '사람을 대할 때 꼭 지키고 싶은 것을 적어 보세요' WHERE `content` = '인간관계에서 가장 중요한 것';
UPDATE `interview_questions` SET `description` = '썸을 탈 때 나만의 기준과 속도를 적어 보세요' WHERE `content` = '썸에 대한 나의 생각(기준, 적정 기간, 스킨십)';
UPDATE `interview_questions` SET `description` = '연애할 때 결혼을 얼마나 생각하는 편인지 적어 보세요' WHERE `content` = '사랑하는 사람이 생겼을 때 결혼에 대한 고려';
UPDATE `interview_questions` SET `description` = '가깝게 지내는 이성 친구가 있는지 적어 보세요' WHERE `content` = '내 주변의 이성 친구들';
UPDATE `interview_questions` SET `description` = '사람들 사이에서 나는 어떤 편인지 적어 보세요' WHERE `content` = '나는 인싸?/아싸?';
UPDATE `interview_questions` SET `description` = '매일 연락하는 사람이 몇 명쯤인지 적어 보세요' WHERE `content` = '매일 연락하고 지내는 사람의 수';
UPDATE `interview_questions` SET `description` = '친구들이 나를 어떤 사람이라고 하는지 적어 보세요' WHERE `content` = '주변 사람들이 말하는 나의 모습';
UPDATE `interview_questions` SET `description` = '얼마나 자주 만나고 연락하고 싶은지 적어 보세요' WHERE `content` = '추구하는 만남 횟수와 연락 빈도';
UPDATE `interview_questions` SET `description` = '연인에게 마음을 어떻게 표현하는 편인지 적어 보세요' WHERE `content` = '내가 연인을 사랑하는 방식';
UPDATE `interview_questions` SET `description` = '연인이 해 주면 고마울 것을 적어 보세요' WHERE `content` = '연인에게 바라는 점';
UPDATE `interview_questions` SET `description` = '연애할 때 가장 소중하게 여기는 것을 적어 보세요' WHERE `content` = '연인 관계에서 가장 중요하다고 생각하는 것';
UPDATE `interview_questions` SET `description` = '함께하고 싶은 데이트를 떠올려 적어 보세요' WHERE `content` = '선호하는 데이트 스타일';
UPDATE `interview_questions` SET `description` = '다퉜을 때 어떻게 풀어 가는 편인지 적어 보세요' WHERE `content` = '연인 사이의 갈등 해소 방법';
UPDATE `interview_questions` SET `description` = '연인에게만 보여 주는 나의 모습을 적어 보세요' WHERE `content` = '연인에게만 보여줄 수 있는 나의 모습';
UPDATE `interview_questions` SET `description` = '연인을 위해 해 줄 수 있는 일을 적어 보세요' WHERE `content` = '연인을 위해 내가 할 수 있는 것';
UPDATE `interview_questions` SET `description` = '연인에게 들려주고 싶은 노래와 이유를 적어 보세요' WHERE `content` = '연인에게 들려주고 싶은 노래';
UPDATE `interview_questions` SET `description` = '연인과 꼭 가 보고 싶은 곳과 이유를 적어 보세요' WHERE `content` = '연인과 함께 가보고 싶은 장소';
